/**
 * Public surface of the feature-art miniatures — split one-file-per-piece
 * under ./feature-art/, re-exported here so consumers (the marketing landing,
 * stories) keep the original import path.
 */
export { SignalArt } from "./feature-art/signal.js";
export { AgentArt } from "./feature-art/agent.js";
export { LeaderboardArt } from "./feature-art/leaderboard.js";
export { AlertArt } from "./feature-art/alert.js";
export { ChatArt } from "./feature-art/chat.js";

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import {
  ArtFrame,
  BEAR,
  BULL,
  BULL_SOFT,
  CARD,
  FG,
  GOLD,
  GOLD_SOFT,
  LINE,
  LOOP,
  MONO,
  MUTED,
  type ArtProps,
} from "./frame.js";

/**
 * Miniature of the real AgentCard from /agents: bot avatar + status dot,
 * "paper · active" subline, the Budget / Balance / P&L stat grid, a budget
 * meter with the daily-loss-cap tick, and the card's sparkline drawing
 * itself. The guardrails aren't a metaphor here — they're the card's own UI.
 */
export function AgentArt({ className }: ArtProps) {
  const reduce = useReducedMotion();
  const meterX = 28;
  const meterW = 264;
  const spentFrac = 0.54;
  const lossTickX = meterX + meterW * 0.8;

  return (
    <ArtFrame className={className}>
      {/* card shell */}
      <rect x={16} y={14} width={288} height={152} rx={12} fill={CARD} stroke={LINE} />

      {/* header: bot avatar, name + status dot, mode subline, kebab */}
      <rect x={28} y={26} width={20} height={20} rx={5} fill={GOLD_SOFT} />
      {/* bot glyph */}
      <rect x={33} y={33} width={10} height={7} rx={2} stroke={GOLD} strokeWidth={1.2} />
      <line x1={38} y1={30} x2={38} y2={33} stroke={GOLD} strokeWidth={1.2} />
      <circle cx={38} cy={29.5} r={1.2} fill={GOLD} />
      <text x={56} y={35} fontSize={10} fill={FG} fontWeight={600}>
        Momentum-1
      </text>
      {reduce ? (
        <circle cx={124} cy={31.5} r={2.5} fill={BULL} />
      ) : (
        <motion.circle
          cx={124}
          cy={31.5}
          r={2.5}
          fill={BULL}
          animate={{ opacity: [1, 0.35, 1] }}
          transition={{ duration: 1.8, repeat: Infinity, ease: "easeInOut" }}
        />
      )}
      <text x={56} y={46} fontSize={7.5} fill={MUTED} fontFamily={MONO}>
        paper · active
      </text>
      {[0, 1, 2].map((i) => (
        <circle key={i} cx={290} cy={29 + i * 4} r={1.1} fill={MUTED} />
      ))}

      {/* stat grid: Budget / Balance / P&L */}
      {[
        { x: 28, label: "Budget", value: "$500" },
        { x: 122, label: "Balance", value: "$543.20" },
      ].map((s) => (
        <g key={s.label}>
          <text x={s.x} y={68} fontSize={7.5} fill={MUTED}>
            {s.label}
          </text>
          <text x={s.x} y={82} fontSize={10.5} fill={FG} fontFamily={MONO} fontWeight={600}>
            {s.value}
          </text>
        </g>
      ))}
      <text x={216} y={68} fontSize={7.5} fill={MUTED}>
        P&amp;L
      </text>
      <g>
        <rect x={216} y={72} width={44} height={14} rx={7} fill={BULL_SOFT} />
        <text
          x={238}
          y={81.5}
          fontSize={8}
          fill={BULL}
          fontFamily={MONO}
          fontWeight={600}
          textAnchor="middle"
        >
          +8.6%
        </text>
      </g>

      {/* budget meter with the daily-loss-cap tick */}
      <text x={28} y={103} fontSize={7} fill={MUTED} fontFamily={MONO}>
        BUDGET USED
      </text>
      <text x={lossTickX - 2} y={103} fontSize={7} fill={BEAR} fontFamily={MONO} opacity={0.85}>
        LOSS CAP
      </text>
      <rect x={meterX} y={108} width={meterW} height={6} rx={3} fill={MUTED} opacity={0.18} />
      <motion.rect
        x={meterX}
        y={108}
        width={meterW * spentFrac}
        height={6}
        rx={3}
        fill={BULL}
        opacity={0.85}
        initial={reduce ? undefined : { scaleX: 0 }}
        animate={reduce ? undefined : { scaleX: [0, 1, 1] }}
        transition={{ duration: 3.4, ease: "easeInOut", times: [0, 0.5, 1], ...LOOP }}
        style={{ transformBox: "fill-box", transformOrigin: "left center" }}
      />
      <line
        x1={lossTickX}
        y1={104}
        x2={lossTickX}
        y2={118}
        stroke={BEAR}
        strokeWidth={1.5}
        strokeDasharray="3 2"
        opacity={0.8}
      />

      {/* sparkline out of the card's own history */}
      <motion.path
        d="M 28 152 L 60 148 L 92 150 L 128 138 L 164 142 L 204 130 L 244 134 L 292 124"
        stroke={BULL}
        strokeWidth={1.8}
        initial={reduce ? undefined : { pathLength: 0, opacity: 0 }}
        animate={reduce ? undefined : { pathLength: [0, 1, 1], opacity: [0, 1, 1] }}
        transition={{ duration: 3.4, ease: "easeOut", times: [0, 0.6, 1], ...LOOP }}
      />
      <motion.circle
        cx={292}
        cy={124}
        r={3}
        fill={BULL}
        initial={reduce ? undefined : { scale: 1 }}
        animate={reduce ? undefined : { scale: [1, 1.5, 1] }}
        transition={{ duration: 1.6, ease: "easeInOut", repeat: Infinity }}
        style={{ transformBox: "fill-box", transformOrigin: "center" }}
      />
    </ArtFrame>
  );
}

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import {
  ArtFrame,
  BULL,
  CARD,
  FG,
  GOLD,
  GOLD_SOFT,
  LINE,
  LOOP,
  MONO,
  MUTED,
  type ArtProps,
} from "./frame.js";

/**
 * Miniature of the /alerts screen: a real alert rule row (toggle, rule text,
 * cadence/channel meta) above its chart. The toggle arms, the price draws
 * through the gold threshold, and exactly one edge-triggered ping fires —
 * with the "Alert fired" chip sliding in like the in-app notification.
 */
export function AlertArt({ className }: ArtProps) {
  const reduce = useReducedMotion();
  const CYCLE = 4.4;
  const crossX = 196;
  const crossY = 122;

  return (
    <ArtFrame className={className}>
      {/* alert rule row */}
      <rect x={16} y={14} width={288} height={44} rx={10} fill={CARD} stroke={LINE} />
      {/* toggle */}
      <rect
        x={28}
        y={29}
        width={24}
        height={14}
        rx={7}
        fill={reduce ? BULL : MUTED}
        opacity={reduce ? 0.55 : 0.25}
      />
      {!reduce && (
        <motion.rect
          x={28}
          y={29}
          width={24}
          height={14}
          rx={7}
          fill={BULL}
          initial={{ opacity: 0 }}
          animate={{ opacity: [0, 0.55, 0.55] }}
          transition={{ duration: CYCLE, times: [0, 0.1, 1], ...LOOP }}
        />
      )}
      {reduce ? (
        <circle cx={46} cy={36} r={5} fill={FG} />
      ) : (
        <motion.circle
          cy={36}
          r={5}
          fill={FG}
          initial={{ cx: 34 }}
          animate={{ cx: [34, 46, 46] }}
          transition={{ duration: CYCLE, times: [0, 0.1, 1], ease: "easeOut", ...LOOP }}
        />
      )}
      <text x={64} y={33} fontSize={9} fill={FG} fontFamily={MONO} fontWeight={600}>
        $PEPE price &gt; $0.000012
      </text>
      <text x={64} y={48} fontSize={7} fill={MUTED} fontFamily={MONO}>
        price threshold · realtime · iMessage
      </text>

      {/* chart strip */}
      <line
        x1={20}
        y1={crossY}
        x2={300}
        y2={crossY}
        stroke={GOLD}
        strokeWidth={1.5}
        strokeDasharray="5 5"
        opacity={0.8}
      />
      <text x={22} y={crossY - 8} fontSize={8} fill={GOLD} fontFamily={MONO}>
        ALERT ABOVE
      </text>
      <motion.path
        d={`M 24 164 L 64 156 L 104 160 L 148 140 L ${crossX} ${crossY} L 240 104 L 296 96`}
        stroke={BULL}
        strokeWidth={2}
        initial={reduce ? undefined : { pathLength: 0 }}
        animate={reduce ? undefined : { pathLength: [0, 0, 1, 1] }}
        transition={{ duration: CYCLE, times: [0, 0.12, 0.62, 1], ease: "easeInOut", ...LOOP }}
      />
      {/* edge-triggered ping at the crossing — exactly one per loop */}
      <circle cx={crossX} cy={crossY} r={4} fill={GOLD} />
      {!reduce && (
        <motion.circle
          cx={crossX}
          cy={crossY}
          r={8}
          stroke={GOLD}
          strokeWidth={1.5}
          initial={{ scale: 0.4, opacity: 0 }}
          animate={{ scale: [0.4, 0.4, 2.4], opacity: [0, 0.9, 0] }}
          transition={{ duration: CYCLE, times: [0, 0.5, 0.75], ease: "easeOut", ...LOOP }}
          style={{ transformBox: "fill-box", transformOrigin: "center" }}
        />
      )}
      {reduce && (
        <circle cx={crossX} cy={crossY} r={11} stroke={GOLD} strokeWidth={1.5} opacity={0.4} />
      )}
      {/* notification chip */}
      {reduce ? (
        <g>
          <rect
            x={196}
            y={70}
            width={104}
            height={20}
            rx={10}
            fill={GOLD_SOFT}
            stroke={GOLD}
            strokeWidth={1}
          />
          <text x={248} y={83} fontSize={7.5} fill={GOLD} fontFamily={MONO} textAnchor="middle">
            Alert fired · $PEPE
          </text>
        </g>
      ) : (
        <motion.g
          initial={{ opacity: 0, y: -8 }}
          animate={{ opacity: [0, 0, 1, 1], y: [-8, -8, 0, 0] }}
          transition={{ duration: CYCLE, times: [0, 0.55, 0.68, 1], ease: "easeOut", ...LOOP }}
        >
          <rect
            x={196}
            y={70}
            width={104}
            height={20}
            rx={10}
            fill={GOLD_SOFT}
            stroke={GOLD}
            strokeWidth={1}
          />
          <text x={248} y={83} fontSize={7.5} fill={GOLD} fontFamily={MONO} textAnchor="middle">
            Alert fired · $PEPE
          </text>
        </motion.g>
      )}
    </ArtFrame>
  );
}

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import {
  ArtFrame,
  BULL,
  CARD,
  CYAN,
  CYAN_SOFT,
  FG,
  GOLD,
  GOLD_SOFT,
  LINE,
  MONO,
  MUTED,
  SECONDARY,
  TextBar,
  type ArtProps,
} from "./frame.js";

/**
 * Miniature of the real /chat surface: the threads rail (ChatThreadsPanel),
 * a user bubble, two streaming tool-call chips that resolve to checks, the
 * assistant's answer card with a blinking caret, and the usage meter — the
 * actual anatomy of a MoneyTrees chat turn.
 */

function ToolChip({
  y,
  label,
  start,
  cycle,
  reduce,
}: {
  y: number;
  label: string;
  start: number;
  cycle: number;
  reduce: boolean | null;
}) {
  const settle = start + 0.14;
  return (
    <motion.g
      initial={reduce ? undefined : { opacity: 0, y: y + 5 }}
      animate={reduce ? undefined : { opacity: [0, 0, 1, 1], y: [y + 5, y + 5, y, y] }}
      transition={{
        duration: cycle,
        times: [0, start, settle, 1],
        ease: "easeOut",
        repeat: Infinity,
      }}
      {...(reduce ? { transform: `translate(0 ${y})` } : {})}
    >
      <rect
        x={104}
        y={0}
        width={118}
        height={18}
        rx={9}
        fill={CYAN_SOFT}
        stroke={CYAN}
        strokeWidth={1}
      />
      <text x={122} y={12} fontSize={8} fill={CYAN} fontFamily={MONO}>
        {label}
      </text>
      {/* spinner arc resolving to a check */}
      {!reduce && (
        <motion.path
          d="M 112 5 A 4 4 0 1 1 108 9"
          stroke={CYAN}
          strokeWidth={1.4}
          initial={{ opacity: 1, rotate: 0 }}
          animate={{ rotate: 360, opacity: [1, 1, 0, 0] }}
          transition={{
            rotate: { duration: 0.9, repeat: Infinity, ease: "linear" },
            opacity: {
              duration: cycle,
              times: [0, settle + 0.1, settle + 0.13, 1],
              repeat: Infinity,
            },
          }}
          style={{ transformBox: "fill-box", transformOrigin: "center" }}
        />
      )}
      <motion.path
        d="M 108 9 L 111 12 L 116 6"
        stroke={CYAN}
        strokeWidth={1.6}
        initial={reduce ? undefined : { opacity: 0 }}
        animate={reduce ? undefined : { opacity: [0, 0, 1, 1] }}
        transition={{
          duration: cycle,
          times: [0, settle + 0.12, settle + 0.15, 1],
          repeat: Infinity,
        }}
      />
    </motion.g>
  );
}

export function ChatArt({ className }: ArtProps) {
  const reduce = useReducedMotion();
  const CYCLE = 7;

  const appear = (start: number, fromY: number, toY: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: fromY },
          animate: { opacity: [0, 0, 1, 1], y: [fromY, fromY, toY, toY] },
          transition: {
            duration: CYCLE,
            times: [0, start, start + 0.08, 1] as number[],
            ease: "easeOut" as const,
            repeat: Infinity,
          },
        };

  return (
    <ArtFrame className={className} viewBox="0 0 320 200">
      {/* threads rail */}
      <rect x={16} y={14} width={76} height={172} rx={10} fill={CARD} stroke={LINE} />
      <text x={26} y={32} fontSize={6.5} fill={MUTED} fontFamily={MONO} letterSpacing={0.8}>
        THREADS
      </text>
      <rect x={72} y={22} width={12} height={12} rx={3.5} fill={GOLD_SOFT} />
      <path d="M 78 25 V 31 M 75 28 H 81" stroke={GOLD} strokeWidth={1.2} />
      {/* active thread */}
      <rect x={22} y={42} width={64} height={16} rx={5} fill={SECONDARY} />
      <TextBar x={27} y={47} w={44} h={6} opacity={0.6} fill={FG} />
      {/* inactive threads */}
      <TextBar x={27} y={68} w={50} h={6} />
      <TextBar x={27} y={84} w={38} h={6} />

      {/* user bubble */}
      <motion.g {...appear(0.03, 27, 22)} {...(reduce ? { transform: "translate(0 22)" } : {})}>
        <rect x={154} y={0} width={150} height={22} rx={10} fill={SECONDARY} />
        <text x={166} y={14.5} fontSize={9} fill={FG}>
          what&apos;s moving today?
        </text>
      </motion.g>

      {/* tool calls, streamed one after the other */}
      <ToolChip y={56} label="trends.recent" start={0.16} cycle={CYCLE} reduce={reduce} />
      <ToolChip y={80} label="watchlist.get" start={0.32} cycle={CYCLE} reduce={reduce} />

      {/* assistant answer card */}
      <motion.g {...appear(0.5, 115, 110)} {...(reduce ? { transform: "translate(0 110)" } : {})}>
        <rect x={104} y={0} width={200} height={52} rx={10} fill={CARD} stroke={LINE} />
        <text x={116} y={19} fontSize={9} fill={FG}>
          $WIF mentions up 340% on /biz/ —
        </text>
        <text x={116} y={34} fontSize={9} fill={FG}>
          momentum crossed your alert line.
        </text>
        {!reduce && (
          <motion.rect
            x={268}
            y={26}
            width={6}
            height={11}
            fill={CYAN}
            animate={{ opacity: [1, 0, 1] }}
            transition={{ duration: 1, repeat: Infinity }}
          />
        )}
      </motion.g>

      {/* usage meter */}
      <text x={104} y={178} fontSize={6.5} fill={MUTED} fontFamily={MONO}>
        TOOL CALLS
      </text>
      <rect x={150} y={173} width={154} height={5} rx={2.5} fill={MUTED} opacity={0.18} />
      <motion.rect
        x={150}
        y={173}
        width={154 * 0.4}
        height={5}
        rx={2.5}
        fill={BULL}
        opacity={0.8}
        initial={reduce ? undefined : { scaleX: 0.3 }}
        animate={reduce ? undefined : { scaleX: [0.3, 0.3, 1, 1] }}
        transition={{ duration: CYCLE, times: [0, 0.32, 0.5, 1], repeat: Infinity }}
        style={{ transformBox: "fill-box", transformOrigin: "left center" }}
      />
    </ArtFrame>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Shared scaffolding for the feature-art miniatures. Each piece is a faithful
 * scaled-down drawing of a real product surface (live-feed table, agent card,
 * leaderboard, alert row, chat) rather than an abstract diagram — redrawn as
 * SVG so it scales crisply, stays out of the a11y tree, and costs nothing at
 * the anonymous first paint.
 *
 * Conventions shared by every piece:
 *  - colors ride theme tokens (`var(--color-*)`) so the art adapts to the
 *    active theme like any other surface;
 *  - `useReducedMotion` renders the finished static frame instead of the
 *    loop — never a blank frame;
 *  - decorative only: `aria-hidden`, meaning lives in the surrounding copy.
 */

export const CYAN = "var(--color-cyan-fg)";
export const CYAN_SOFT = "var(--color-cyan-soft)";
export const BULL = "var(--color-bull-fg)";
export const BULL_SOFT = "var(--color-bull-soft)";
export const BEAR = "var(--color-bear-fg)";
export const BEAR_SOFT = "var(--color-bear-soft)";
export const GOLD = "var(--color-gold)";
export const GOLD_SOFT = "var(--color-gold-soft)";
export const LINE = "var(--color-border)";
export const MUTED = "var(--color-muted-foreground)";
export const FG = "var(--color-foreground)";
export const CARD = "var(--color-card)";
export const SECONDARY = "var(--color-secondary)";
export const MONO = "var(--font-mono)";

export type ArtProps = { className?: string };

export function ArtFrame({
  className,
  viewBox = "0 0 320 180",
  children,
}: ArtProps & { viewBox?: string; children: React.ReactNode }) {
  return (
    <svg
      viewBox={viewBox}
      aria-hidden
      className={cn("h-auto w-full", className)}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {children}
    </svg>
  );
}

export const LOOP = { repeat: Infinity, repeatDelay: 0.4 } as const;

/** Rounded placeholder bar standing in for a line of real text. */
export function TextBar({
  x,
  y,
  w,
  h = 8,
  opacity = 0.25,
  fill = MUTED,
}: {
  x: number;
  y: number;
  w: number;
  h?: number;
  opacity?: number;
  fill?: string;
}) {
  return <rect x={x} y={y} width={w} height={h} rx={h / 2} fill={fill} opacity={opacity} />;
}

interface MiniChipProps {
  x: number;
  y: number;
  w: number;
  h?: number;
  label: string;
  color: string;
  soft: string;
  fontSize?: number;
}

/** Small rounded chip with centered mono text — source tags, tickers, PnL. */
export function MiniChip({ x, y, w, h = 14, label, color, soft, fontSize = 8 }: MiniChipProps) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={h / 2} fill={soft} />
      <text
        x={x + w / 2}
        y={y + h / 2 + fontSize * 0.36}
        fontSize={fontSize}
        fill={color}
        fontFamily={MONO}
        textAnchor="middle"
      >
        {label}
      </text>
    </g>
  );
}

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import {
  ArtFrame,
  BULL,
  CARD,
  FG,
  GOLD,
  GOLD_SOFT,
  LINE,
  LOOP,
  MONO,
  MUTED,
  TextBar,
  type ArtProps,
} from "./frame.js";

/**
 * Miniature of the /leaderboards Polymarket board: the rounded tab strip
 * (Polymarket · Congress · Truth), ranked rows with avatar + name + mono
 * PnL — and the board's real story: the wallet in rank 2 prints a bigger
 * number and swaps into the lead under a gold flash.
 */

const SLOTS = [52, 82, 112, 142] as const;
const RANK_COLORS = [GOLD, "var(--color-silver)", "var(--color-bronze)", MUTED] as const;

function Row({ nameW, pnl, pnlColor }: { nameW: number; pnl: string; pnlColor: string }) {
  return (
    <>
      <circle cx={52} cy={11} r={7} fill={MUTED} opacity={0.3} />
      <TextBar x={68} y={7} w={nameW} />
      <text
        x={292}
        y={15}
        fontSize={9.5}
        fill={pnlColor}
        fontFamily={MONO}
        fontWeight={600}
        textAnchor="end"
      >
        {pnl}
      </text>
    </>
  );
}

export function LeaderboardArt({ className }: ArtProps) {
  const reduce = useReducedMotion();
  // One cycle: challenger's PnL ticks up, then rows 1 and 2 trade places and
  // the new leader flashes gold.
  const CYCLE = 4.6;
  const swapTimes = [0, 0.35, 0.55, 1] as const;

  return (
    <ArtFrame className={className}>
      {/* tab strip */}
      <rect x={16} y={14} width={196} height={22} rx={11} fill={MUTED} opacity={0.12} />
      <rect x={19} y={16.5} width={72} height={17} rx={8.5} fill={CARD} stroke={LINE} />
      <text x={55} y={28} fontSize={8} fill={FG} textAnchor="middle" fontWeight={600}>
        Polymarket
      </text>
      <text x={126} y={28} fontSize={8} fill={MUTED} textAnchor="middle">
        Congress
      </text>
      <text x={183} y={28} fontSize={8} fill={MUTED} textAnchor="middle">
        Truth
      </text>

      {/* fixed rank numerals — ranks stay put, wallets move through them */}
      {SLOTS.map((y, i) => (
        <text
          key={y}
          x={28}
          y={y + 15}
          fontSize={10}
          fill={RANK_COLORS[i]}
          fontFamily={MONO}
          fontWeight={i === 0 ? 700 : 400}
        >
          {i + 1}
        </text>
      ))}

      {reduce ? (
        <>
          <g transform={`translate(0 ${SLOTS[0]})`}>
            <rect x={40} y={0} width={264} height={22} rx={6} fill={GOLD_SOFT} />
            <Row nameW={96} pnl="+$1.4M" pnlColor={BULL} />
          </g>
          <g transform={`translate(0 ${SLOTS[1]})`}>
            <Row nameW={84} pnl="+$1.1M" pnlColor={BULL} />
          </g>
          <g transform={`translate(0 ${SLOTS[2]})`}>
            <Row nameW={72} pnl="+$620K" pnlColor={BULL} />
          </g>
          <g transform={`translate(0 ${SLOTS[3]})`}>
            <Row nameW={90} pnl="+$180K" pnlColor={MUTED} />
          </g>
        </>
      ) : (
        <>
          {/* incumbent leader: slides down to rank 2 */}
          <motion.g
            initial={{ y: SLOTS[0] }}
            animate={{ y: [SLOTS[0], SLOTS[0], SLOTS[1], SLOTS[1]] }}
            transition={{ duration: CYCLE, times: [...swapTimes], ease: "easeInOut", ...LOOP }}
          >
