            animate={{ y: [SLOTS[1], SLOTS[1], SLOTS[0], SLOTS[0]] }}
            transition={{ duration: CYCLE, times: [...swapTimes], ease: "easeInOut", ...LOOP }}
          >
            <motion.rect
              x={40}
              y={0}
              width={264}
              height={22}
              rx={6}
              fill={GOLD_SOFT}
              initial={{ opacity: 0 }}
