"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

import {
  ArtFrame,
  BULL,
  BULL_SOFT,
  BEAR,
  BEAR_SOFT,
  CARD,
  CYAN,
  CYAN_SOFT,
  FG,
  GOLD_SOFT,
  LINE,
  LOOP,
  MiniChip,
  MONO,
  MUTED,
  TextBar,
  type ArtProps,
} from "./frame.js";

/**
 * Miniature of the dashboard's live signal feed (LiveFeedTable): source,
 * signal text, sentiment, ticker — with the real table's signature move, a
 * fresh row dropping in on top with the gold new-row wash while the rest of
 * the feed shifts down.
 */

type Row = {
  source: string;
  barW: number;
  sent: string;
  bull: boolean;
  ticker: string;
};

const INCOMING: Row = { source: "X", barW: 96, sent: "+340%", bull: true, ticker: "$WIF" };
const ROWS: Row[] = [
  { source: "POLY", barW: 78, sent: "+64%", bull: true, ticker: "$TRUMP" },
  { source: "/biz/", barW: 104, sent: "+128%", bull: true, ticker: "$PEPE" },
  { source: "KALSHI", barW: 64, sent: "-22%", bull: false, ticker: "$DOGE" },
  { source: "X", barW: 88, sent: "+41%", bull: true, ticker: "$MOG" },
];

const SLOT_TOPS = [46, 76, 106, 136];
const SLOT_H = 30;

function RowContent({ row, highlight }: { row: Row; highlight?: boolean }) {
  return (
    <>
      {highlight && <rect x={17} y={0} width={286} height={SLOT_H - 2} rx={6} fill={GOLD_SOFT} />}
      <MiniChip x={24} y={7} w={38} label={row.source} color={CYAN} soft={CYAN_SOFT} fontSize={7} />
      <TextBar x={72} y={10} w={row.barW} />
      <MiniChip
        x={200}
        y={7}
        w={38}
        label={row.sent}
        color={row.bull ? BULL : BEAR}
        soft={row.bull ? BULL_SOFT : BEAR_SOFT}
        fontSize={7}
      />
      <text x={248} y={17} fontSize={8.5} fill={FG} fontFamily={MONO} fontWeight={600}>
        {row.ticker}
      </text>
    </>
  );
}

export function SignalArt({ className }: ArtProps) {
  const reduce = useReducedMotion();
  // One cycle: the incoming row drops into slot 0 under a gold wash while
  // every resident row shifts down a slot and the last one fades out.
  const CYCLE = 4.2;
  // Clip animated rows to the table body so the drop-in and the fading last
  // row never bleed over the table border. useId keeps the clipPath unique
  // when several instances share a page (landing + stories).
  const clipId = React.useId();

  return (
    <ArtFrame className={className}>
      {/* table shell */}
      <rect x={16} y={14} width={288} height={152} rx={10} fill={CARD} stroke={LINE} />
      <clipPath id={clipId}>
        <rect x={17} y={41} width={286} height={124} rx={8} />
      </clipPath>
      {/* header */}
      {[
        { x: 24, label: "SOURCE" },
        { x: 72, label: "SIGNAL" },
        { x: 200, label: "SENT" },
        { x: 248, label: "TICKER" },
      ].map((h) => (
        <text key={h.label} x={h.x} y={33} fontSize={7} fill={MUTED} fontFamily={MONO}>
          {h.label}
        </text>
      ))}
      <line x1={16} y1={40} x2={304} y2={40} stroke={LINE} strokeWidth={1} />

      {reduce ? (
        <>
          <g transform={`translate(0 ${SLOT_TOPS[0]})`}>
            <RowContent row={INCOMING} highlight />
          </g>
          {ROWS.slice(0, 3).map((row, i) => (
            <g key={row.ticker} transform={`translate(0 ${SLOT_TOPS[i + 1]})`}>
              <RowContent row={row} />
            </g>
          ))}
        </>
      ) : (
        <g clipPath={`url(#${clipId})`}>
          {/* incoming row: drops in from above the table under a fading wash */}
          <motion.g
            initial={{ y: SLOT_TOPS[0]! - 18, opacity: 0 }}
            animate={{ y: [SLOT_TOPS[0]! - 18, SLOT_TOPS[0]!, SLOT_TOPS[0]!], opacity: [0, 1, 1] }}
            transition={{ duration: CYCLE, times: [0, 0.12, 1], ease: "easeOut", ...LOOP }}
          >
            <motion.rect
              x={17}
              y={0}
              width={286}
              height={SLOT_H - 2}
              rx={6}
              fill={GOLD_SOFT}
              initial={{ opacity: 0 }}
              animate={{ opacity: [0, 1, 1, 0] }}
              transition={{ duration: CYCLE, times: [0, 0.12, 0.4, 0.7], ...LOOP }}
            />
            <RowContent row={INCOMING} />
          </motion.g>
          {/* resident rows shift down one slot; the last fades out */}
          {ROWS.map((row, i) => {
            const from = SLOT_TOPS[i]!;
            const isLast = i === ROWS.length - 1;
            const to = isLast ? from + 12 : SLOT_TOPS[i + 1]!;
            return (
              <motion.g
                key={row.ticker}
                initial={{ y: from, opacity: 1 }}
                animate={{
                  y: [from, to, to],
                  opacity: isLast ? [1, 0, 0] : [1, 1, 1],
                }}
                transition={{ duration: CYCLE, times: [0, 0.12, 1], ease: "easeOut", ...LOOP }}
              >
                <RowContent row={row} />
              </motion.g>
            );
          })}
        </g>
      )}
    </ArtFrame>
  );
}
